func CoreLaws() []string {
	return []string{
		"PATTERN != PROOF",
		"PROFILE != PERSON",
		"MODEL != MIND",
		"PREDICTION != DESTINY",
		"CAPABILITY != AUTHORITY",
		"ACCESS != CONSENT",
		"ERROR != GUILT",
		"UNKNOWN != FALSE",
		"DIFFERENCE != DEFECT",
		"SIGNAL != VERDICT",
		"DATA != CONTEXT",
		"INTERPRETATION != EVENT",
		"REPRESENTATION != PRESENCE",
		"CONFIDENCE != CERTAINTY",
		"RECOVERY > PROPAGATION",
		"HUMAN_AGENCY > MACHINE_AUTHORITY",
		"MACHINE_CAN_READ != MACHINE_CAN_DEFINE",
	}
}
